  /** true면 반품지 3필드를 쓰지 않고 출고지를 반품지로 본다. 서버가 이 값으로 반품지 저장 여부를 가르므로 화면의 체크 상태를 그대로 싣는다 */
  returnSameAsOrigin: boolean
