  /** 비밀글도 셀러에게는 본문이 그대로 내려온다(답변 당사자) */
  content: string
  /** 마스킹된 작성자 표시명(예: 김**). 닉네임이 없으면 '익명' */
  authorMasked: string
  /** 비밀글 — 작성자와 이 셀러만 본문을 읽는다 */
  secret: boolean
  status: ProductInquiryStatus
  askedAt: string
  /** 서버가 접수 시점에 계산한 답변 기한(영업일 2일, 주말 제외) */
  answerDueAt: string
  /** 미답변 상태로 기한을 넘겼는지 — 서버 판정 결과다 */
